typedef unsigned char u8;
typedef unsigned int u16;
volatile u16 sum;
volatile u8 high_byte;
void main(void) { u8 a=250,b=10; sum=(u16)a+b; P1=(u8)sum;
 high_byte=(u8)(sum>>8); for (;;) { } }

#include <reg51.h>
typedef unsigned char u8;
typedef unsigned int u16;
volatile u8 low_byte,borrow;
void main(void) { u8 a=10,b=25; borrow=(a<b); low_byte=(u8)(a-b);
 P0=low_byte; for (;;) { } }
